using GraphApi.Models.USR.TiposMascota;namespace GraphApi.Services.USR.TiposMascota{    /// <summary>    /// Define las operaciones de negocio y persistencia para TiposMascotas.    /// </summary>    public interface ITiposMascotaService    {        /// <summary>        /// Obtiene la lista de TiposMascotas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadTiposMascota>> GetTiposMascotas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de TiposMascotas con filtros opcionales.        /// </summary>        /// <param name="tipoMascotaID">Filtro opcional para TipoMascotaID.</param>        /// <param name="tipoMascota">Filtro opcional para TipoMascota.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetTiposMascotasDynamic(            int? tipoMascotaID,            string? tipoMascota,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo TiposMascota.        /// </summary>        /// <param name="objInput">Datos para crear el TiposMascota.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTiposMascota> CreateTiposMascota(            clCreateTiposMascota objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un TiposMascota.        /// </summary>        /// <param name="objInput">Datos para actualizar el TiposMascota, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTiposMascota?> UpdateTiposMascota(            clUpdateTiposMascota objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un TiposMascota por su ID.        /// </summary>        /// <param name="nTiposMascotaID">ID del TiposMascota a eliminar.</param>        Task<bool> DeleteTiposMascota(int nTiposMascotaID);    }}